#include "canvas/ink/brush_session.hpp"
#include <limits>
namespace canvas::ink { BrushSession::BrushSession(std::uint64_t id,ResolvedBrushState state):id_(id),state_(std::move(state)){} bool BrushSession::begin(){if(active_||id_==0)return false;active_=true;return true;} BrushSessionError BrushSession::append(std::span<const BrushSample> confirmed,std::span<const BrushSample> predicted,BrushPreviewDelta& out){if(!active_){error_=BrushSessionError::kInvalid;return error_;}auto sequence=lastSequence_;for(const auto& sample:confirmed){if(sample.sequence==0||sample.sequence<=sequence){error_=BrushSessionError::kSequence;return error_;}if(state_.package.vector.pressureSource==BrushPressureSource::kDevice&&!sample.pressurePresent&&state_.package.vector.missingPressure==BrushMissingPressure::kReject){error_=BrushSessionError::kPressure;return error_;}sequence=sample.sequence;}std::vector<reference::VectorStrokeInput> input;input.reserve(confirmed_.size()+confirmed.size()+predicted.size());for(const auto& sample:confirmed_)input.push_back({sample.x,sample.y,sample.pressurePresent?sample.pressure:std::numeric_limits<double>::quiet_NaN()});for(const auto& sample:confirmed){confirmed_.push_back(sample);input.push_back({sample.x,sample.y,sample.pressurePresent?sample.pressure:std::numeric_limits<double>::quiet_NaN()});lastSequence_=sample.sequence;}for(const auto& sample:predicted)input.push_back({sample.x,sample.y,sample.pressurePresent?sample.pressure:std::numeric_limits<double>::quiet_NaN()});auto result=VectorPathNode(state_).evaluate(input,false);out={++revision_,std::move(result.outline)};error_=BrushSessionError::kNone;return error_;} BrushSessionError BrushSession::seal(BrushCommitIntent& out){if(!active_||confirmed_.empty()){error_=BrushSessionError::kEmpty;return error_;}std::vector<reference::VectorStrokeInput> input;for(const auto& sample:confirmed_)input.push_back({sample.x,sample.y,sample.pressurePresent?sample.pressure:std::numeric_limits<double>::quiet_NaN()});auto result=VectorPathNode(state_).evaluate(input,true);if(!result){error_=BrushSessionError::kEmpty;return error_;}out={id_,++revision_,state_.seed,confirmed_,std::move(result.outline)};active_=false;return error_=BrushSessionError::kNone;}void BrushSession::cancel()noexcept{active_=false;confirmed_.clear();}}
